def step(msg):
    w(('\n===== %s =====\n' % msg).encode())

def wait_login(timeout):
    end = time.time() + timeout
    last_nudge = 0
    while time.time() < end:
        if re.search(r'login:', buf.decode('utf-8', 'replace'), re.I):
            return
        if time.time() - last_nudge > 3:
            try:
                s.sendall(b'\r\n')
            except Exception:
                pass
            last_nudge = time.time()
        pump(1)
    raise TimeoutError('no login prompt; tail=%r' % buf[-1500:])

try:
    step('waiting for login prompt')
    wait_login(1500)
    step('saw login prompt')
    buf = b''

